commands.command:
cat > /tmp/convert_latin1_names.pl <<'ANTRIEB_EOF'
use strict;
use warnings;
use Encode qw(decode encode FB_CROAK);
use File::Find;
use File::Path qw(mkpath);
use Fcntl qw(O_WRONLY O_CREAT O_EXCL);

my $base = '/srv/legacy2/filename-encoding-migration';
my $srcroot = "$base/imported";
my $dstroot = "$base/converted";
my @entries;
find({ no_chdir => 1, wanted => sub { push @entries, $File::Find::name if $File::Find::name ne $srcroot } }, $srcroot);
@entries = sort { (($a =~ tr{/}{/}) <=> ($b =~ tr{/}{/})) || ($a cmp $b) } @entries;
mkpath($dstroot) unless -d $dstroot;
my @report;
my ($copied, $collisions, $dirs) = (0, 0, 0);
for my $source (@entries) {
    my $rel = substr($source, length($srcroot) + 1);
    my $utf8rel = encode('UTF-8', decode('ISO-8859-1', $rel, FB_CROAK));
    my $dest = "$dstroot/$utf8rel";
    if (-d $source) {
        my @dststat = lstat($dest);
        if (@dststat && !-d _) {
            push @report, "COLLISION\timported/$rel\tconverted/$utf8rel\n";
            $collisions++;
            next;
        }
        if (!@dststat) {
            mkdir($dest, (stat($source))[2] & 07777) or die "mkdir $dest: $!";
            $dirs++;
        }
        next;
    }
    die "unsupported source object: $source" unless -f $source;
    my @dststat = lstat($dest);
    if (@dststat) {
        push @report, "COLLISION\timported/$rel\tconverted/$utf8rel\n";
        $collisions++;
        next;
    }
    open(my $in, '<', $source) or die "open source $source: $!";
    binmode($in);
    if (!sysopen(my $out, $dest, O_WRONLY|O_CREAT|O_EXCL, 0600)) {
        close($in);
        push @report, "COLLISION\timported/$rel\tconverted/$utf8rel\n";
        $collisions++;
        next;
    } else {
        binmode($out);
        my $buffer;
        while (1) {
            my $n = read($in, $buffer, 65536);
            die "read $source: $!" unless defined $n;
            last if $n == 0;
            print {$out} $buffer or die "write $dest: $!";
        }
        close($out) or die "close $dest: $!";
        close($in) or die "close $source: $!";
        my @st = stat($source);
        chmod($st[2] & 07777, $dest) or die "chmod $dest: $!";
        utime($st[8], $st[9], $dest) or die "utime $dest: $!";
        push @report, "COPIED\timported/$rel\tconverted/$utf8rel\n";
        $copied++;
    }
}
my $report_tmp = "$base/conversion-report.txt.tmp.$$";
open(my $rf, '>', $report_tmp) or die "open report: $!";
binmode($rf);
print {$rf} "source_encoding=ISO-8859-1\nfilename_encoding=UTF-8\n";
print {$rf} @report;
print {$rf} "summary\tcopied=$copied\tcollisions=$collisions\tdirectories_created=$dirs\n";
close($rf) or die "close report: $!";
rename($report_tmp, "$base/conversion-report.txt") or die "publish report: $!";
print "copied=$copied collisions=$collisions directories_created=$dirs\n";
ANTRIEB_EOF
perl -c /tmp/convert_latin1_names.pl

