commands.command:
cat > /tmp/reconcile_conversion_report.pl <<'ANTRIEB_EOF'
use strict;
use warnings;
use Encode qw(decode encode FB_CROAK);
use File::Find;
sub same_bytes {
    my ($left, $right) = @_;
    open(my $a, '<', $left) or die "open $left: $!";
    open(my $b, '<', $right) or die "open $right: $!";
    binmode($a); binmode($b);
    while (1) {
        my ($ab, $bb);
        my $an = read($a, $ab, 65536); my $bn = read($b, $bb, 65536);
        die "read failure" unless defined($an) && defined($bn);
        return 0 if $an != $bn || $ab ne $bb;
        return 1 if $an == 0;
    }
}
my $base = '/srv/legacy2/filename-encoding-migration';
my $srcroot = "$base/imported";
my @files;
find({ no_chdir => 1, wanted => sub { push @files, $File::Find::name if -f $File::Find::name } }, $srcroot);
@files = sort @files;
my @lines;
my ($matched, $collisions, $missing) = (0, 0, 0);
for my $source (@files) {
    my $rawrel = substr($source, length($srcroot) + 1);
    my $decode_input = $rawrel;
    my $utf8rel = encode('UTF-8', decode('ISO-8859-1', $decode_input, FB_CROAK));
    my $dest = "$base/converted/$utf8rel";
    my $source_hex = unpack('H*', $rawrel);
    if (!-e $dest) {
        push @lines, "MISSING\tsource_name_latin1_hex=$source_hex\tsource_display_utf8=imported/$utf8rel\tdestination=converted/$utf8rel\n";
        $missing++;
    } elsif (same_bytes($source, $dest)) {
        push @lines, "VERIFIED_CONTENT_MATCH\tsource_name_latin1_hex=$source_hex\tsource_display_utf8=imported/$utf8rel\tdestination=converted/$utf8rel\n";
        $matched++;
    } else {
        push @lines, "COLLISION_PRESERVED\tsource_name_latin1_hex=$source_hex\tsource_display_utf8=imported/$utf8rel\tdestination=converted/$utf8rel\n";
        $collisions++;
    }
}
my $tmp = "$base/conversion-report.txt.tmp.$$";
open(my $out, '>', $tmp) or die "open report: $!";
binmode($out);
print {$out} "source_encoding=ISO-8859-1\nfilename_encoding=UTF-8\n";
print {$out} @lines;
print {$out} "summary\tverified_content_matches=$matched\tcollisions_preserved=$collisions\tmissing=$missing\n";
close($out) or die "close report: $!";
rename($tmp, "$base/conversion-report.txt") or die "publish report: $!";
print "verified_content_matches=$matched collisions_preserved=$collisions missing=$missing\n";
ANTRIEB_EOF
perl -c /tmp/reconcile_conversion_report.pl
perl /tmp/reconcile_conversion_report.pl
cat /srv/legacy2/filename-encoding-migration/conversion-report.txt
